(* [comment removed for export] *)
Lemma append_sso_x : forall (LB : list (Z * Z)) (cr : credit) (o q sp r : Z) (s src : list Z),
  PML.cps_heap L HI PML.PC_STR_APPEND r sp PMS.STR_SCR LB cr
      (fun R M => (1 <= len src /\ len s + len src <= 22) /\ PML.entry L R M sp r PMS.STR_SCR /\ PML.a0 R o /\ PML.a1 R q /\ PML.a2 R (len src) /\
                  PML.str_at M o (PML.SShort s) /\ L5.defined M o 24 /\ PML.obj_on_stack L sp o 24 /\
                  L5.bytes_at GK.RSEGS M q src /\ PMES.src_ok L M LB sp o (PML.SShort s) q (len src))
